    // ---------------------------------------------------- Bab 2 Bantuan Kecemasan
    bantuan_kecemasan: [
      Q("Apakah resusitasi kardiopulmonari (CPR)?", "Bantuan kecemasan yang menggabungkan tekanan di dada dan hembusan ke dalam mulut mangsa untuk mengembalikan degupan jantung dan pernafasan", ["Kaedah menyentak perut mangsa yang tercekik", "Kaedah mengukur tekanan darah mangsa", "Kaedah membalut luka mangsa"], "Buku teks: CPR menggabungkan teknik tekanan di bahagian dada dan hembusan ke dalam mulut mangsa.", "L"),
      Q("Antara berikut, yang manakah keadaan yang memerlukan CPR?", "Individu tidak memberikan respons, tidak bernafas dan tiada degupan jantung atau nadi", ["Individu bersin berulang kali", "Individu mengadu sakit kepala ringan", "Individu sedang tidur lena dan bernafas dengan normal"], "Buku teks: CPR diperlukan jika individu tidak memberikan respons, tidak bernafas atau tiada degupan jantung atau nadi.", "L"),
      Q("Apakah nombor talian kecemasan di Malaysia?", "999", ["888", "911", "100"], "Buku teks: talian kecemasan di Malaysia ialah 999.", "L"),
      Q("Bagaimanakah saluran pernafasan mangsa dibuka semasa CPR?", "Mendongakkan kepala mangsa ke belakang dan mengangkat dagunya", ["Menundukkan kepala mangsa ke hadapan", "Memusingkan kepala mangsa ke tepi berulang kali", "Menutup mulut mangsa"], "Buku teks: dongakkan kepala mangsa ke belakang dan angkat dagunya untuk membuka saluran pernafasan.", "M"),
      Q("Di manakah tapak tangan diletakkan semasa melakukan tekanan dada pada mangsa dewasa?", "Di bahagian tengah dada mangsa", ["Di perut mangsa", "Di bahu mangsa", "Di leher mangsa"], "Buku teks: letakkan sebelah tapak tangan di bahagian tengah dada mangsa, tekup dengan tangan sebelah lagi dan selang-selikan jari.", "M"),
      Q("Menurut buku teks, sedalam berapakah dada dewasa ditekan semasa CPR?", "Lebih kurang 5 cm dan tidak lebih daripada 6 cm", ["Lebih kurang 1 cm", "Lebih kurang 10 cm", "Lebih kurang 15 cm"], "Buku teks: tekan ke bawah lebih kurang 5 cm dan tidak lebih daripada 6 cm.", "H"),
      Q("Berapakah kadar tekanan dada semasa CPR menurut buku teks?", "100 - 120 tekanan per minit", ["20 - 40 tekanan per minit", "50 - 60 tekanan per minit", "200 - 220 tekanan per minit"], "Buku teks: tekanan dada dilakukan pada kadar 100 - 120 tekanan per minit.", "H"),
      Q("Berapa lama setiap hembusan dalam bantuan pernafasan mulut ke mulut?", "1 saat", ["10 saat", "30 saat", "1 minit"], "Buku teks: picit hidung mangsa dan hembuskan udara ke dalam mulutnya selama 1 saat setiap hembusan.", "M"),
      Q("Apakah nisbah tekanan dada kepada hembusan mulut ke mulut dalam CPR menurut buku teks?", "30 tekanan dada diikuti 2 hembusan", ["2 tekanan dada diikuti 30 hembusan", "15 tekanan dada diikuti 15 hembusan", "30 tekanan dada diikuti 30 hembusan"], "Buku teks: tekanan dada 30 kali diikuti 2 kali hembusan mulut ke mulut, diulang sehingga ambulans tiba atau mangsa sedar.", "M"),
      Q("Jika mangsa sudah bernafas tetapi masih belum sedar, apakah yang perlu dilakukan?", "Ubah kedudukan badan mangsa dalam keadaan mengiring", ["Teruskan tekanan dada", "Biarkan mangsa terlentang tanpa sebarang tindakan", "Beri mangsa makan dan minum"], "Buku teks: jika mangsa bernafas tetapi belum sedar, ubah kedudukan badannya dalam keadaan mengiring.", "M"),
      Q("Mengapakah tekanan dada penting dalam CPR?", "Menghasilkan peredaran darah secara buatan dengan mengepam darah melalui jantung", ["Memanaskan badan mangsa", "Membuka saluran pernafasan yang tersumbat makanan", "Menurunkan suhu badan mangsa"], "Buku teks: tekanan dada menghasilkan peredaran darah secara buatan dengan mengepam darah melalui jantung, terutama bagi mangsa serangan jantung.", "M"),
      Q("Apakah yang dimaksudkan dengan tercekik?", "Saluran pernafasan tersekat disebabkan oleh makanan atau bendasing", ["Jantung berhenti berdegup", "Paru-paru dipenuhi air", "Otot leher mengecut kerana sejuk"], "Buku teks: tercekik ialah keadaan apabila saluran pernafasan tersekat disebabkan oleh makanan atau bendasing.", "L"),
      Q("Siapakah yang menemui kaedah Heimlich Manoeuvre pada tahun 1974?", "Dr. Henry Heimlich", ["Dr. Tabata Izumi", "Dr. Gosta Holmer", "Dr. Robert Oppenheimer"], "Buku teks: pada tahun 1974, Dr. Henry Heimlich, seorang pakar bedah toraks, menemui kaedah Heimlich Manoeuvre.", "H"),
      Q("Antara berikut, yang manakah situasi mangsa yang memerlukan Heimlich Manoeuvre?", "Memegang leher dengan kedua-dua tangan dan tidak boleh bercakap atau batuk", ["Mengadu keletihan selepas bersenam", "Bercakap dan batuk dengan kuat", "Menggigil kerana demam"], "Buku teks: mangsa memegang leher dengan kedua-dua tangan, tidak boleh bercakap atau batuk, sukar bernafas dan kulit, bibir serta kuku kelihatan kebiruan.", "M"),
      Q("Semasa Heimlich Manoeuvre, di manakah genggaman tangan diletakkan pada badan mangsa?", "Di antara pusat dengan bawah rusuk", ["Di bahagian tengah dada", "Di leher mangsa", "Di belakang kepala mangsa"], "Buku teks: letakkan genggaman tangan kanan di antara pusat dengan bawah rusuk mangsa dan tangan kiri di atasnya, kemudian tekan dan sentak ke atas dengan kuat dan cepat.", "M"),
      Q("Apakah yang berlaku kepada epiglotis semasa seseorang menelan makanan?", "Epiglotis terlipat dan menutup trakea supaya makanan masuk ke esofagus", ["Epiglotis membuka trakea supaya makanan masuk ke peparu", "Epiglotis menyedut makanan ke dalam peparu", "Epiglotis tidak bergerak"], "Buku teks: apabila seseorang menelan makanan, epiglotis terlipat dan menutup trakea; makanan bergerak ke esofagus menuju ke perut.", "H")
    ],

