    // ---------------------------------------------------- Bab 9 Kimia Industri (9.3 Polimer)
    polimer_getah: [
      Q("Apakah polimer, dan apakah unit kecil yang membentuknya?", "Molekul besar berbentuk rantai; unit kecilnya ialah monomer", ["Molekul kecil berbentuk bulat; unit kecilnya ialah atom", "Campuran logam; unit kecilnya ialah aloi", "Larutan cecair; unit kecilnya ialah ion"], "Buku teks: polimer ialah molekul besar berbentuk rantai yang terdiri daripada gabungan unit molekul kecil yang dikenal sebagai monomer.", "L"),
      Q("Apakah monomer bagi protein?", "Asid amino", ["Glukosa", "Isoprena", "Etena"], "Buku teks: protein = monomer asid amino; kanji = glukosa; getah asli = isoprena; polietena = etena.", "M"),
      Q("Polietena dihasilkan daripada monomer yang manakah?", "Etena", ["Stirena", "Isoprena", "Neoprena"], "Buku teks: polietena dihasilkan daripada monomer etena melalui pempolimeran penambahan.", "M"),
      Q("Perspeks (polimer sintetik) digunakan untuk membuat ...", "cermin pesawat dan tingkap kenderaan", ["sarung tangan dan tayar", "bekas pembungkusan peralatan elektrik", "botol plastik dan baldi"], "Buku teks: perspeks (monomer metil metakrilat) untuk cermin pesawat dan tingkap kenderaan; getah sintetik untuk sarung tangan, tayar dan tapak kasut; polistirena untuk bekas pembungkusan.", "H"),
      Q("Apakah pempolimeran?", "Proses pencantuman monomer melalui pembentukan ikatan kimia untuk menghasilkan polimer berbentuk rantai", ["Proses memisahkan polimer kepada monomer", "Proses memanaskan getah dengan sulfur", "Proses menggumpalkan lateks dengan alkali"], "Buku teks: pempolimeran ialah pencantuman monomer; penyahpolimeran ialah pemisahan polimer kepada monomer melalui tindak balas kimia.", "M"),
      Q("Mengapakah lateks kekal sebagai cecair?", "Molekul getah dikelilingi cas negatif pada membran protein, maka saling menolak", ["Molekul getah saling menarik antara satu sama lain", "Lateks mengandungi sulfur", "Lateks mengandungi banyak ion hidrogen positif"], "Buku teks: dalam lateks, molekul getah diselaputi membran protein yang dikelilingi cas negatif; molekul getah saling menolak maka lateks kekal cecair.", "H"),
      Q("Mengapakah lateks menggumpal apabila asid ditambah?", "Ion hidrogen meneutralkan cas negatif pada membran protein, lalu molekul getah berlanggar dan berbelit", ["Ion hidroksida menambah cas negatif pada membran", "Asid menambah air ke dalam lateks", "Asid memecahkan monomer getah menjadi atom"], "Buku teks: ion hidrogen bercas positif meneutralkan cas negatif pada membran protein; molekul getah berlanggar, membran pecah dan rantai getah berbelit membentuk gumpalan.", "H"),
      Q("Apakah yang berlaku apabila alkali seperti larutan ammonia ditambah ke dalam lateks?", "Lateks kekal cecair", ["Lateks menggumpal dengan cepat", "Lateks bertukar menjadi pepejal keras", "Lateks menjadi getah tervulkan"], "Buku teks: ion hidroksida meneutralkan ion hidrogen daripada asid; cas negatif kekal pada membran protein dan lateks kekal cecair.", "M"),
      Q("Apakah pemvulkanan getah?", "Proses memanaskan getah bersama sulfur", ["Proses menyejukkan getah dengan air", "Proses menambah asid ke dalam lateks", "Proses menggabungkan getah dengan besi"], "Buku teks: pemvulkanan ialah proses pemanasan getah bersama sulfur; getah yang diperoleh disebut getah tervulkan.", "M"),
      Q("Siapakah yang menemui kaedah pemvulkanan getah pada tahun 1839?", "Charles Goodyear", ["Henry Heimlich", "Isaac Newton", "Gregor Mendel"], "Buku teks: Charles Goodyear (1800-1860) menemui kaedah pemvulkanan pada tahun 1839 dengan memanaskan getah asli dengan 1%-3% sulfur mengikut jisim.", "H"),
      Q("Mengapakah getah tervulkan lebih keras dan lebih tahan haba daripada getah asli?", "Atom sulfur menghasilkan rangkai silang antara rantai polimer getah", ["Atom sulfur memisahkan rantai polimer menjadi monomer", "Getah tervulkan tidak mempunyai rantai polimer", "Atom sulfur menyebabkan getah lebih lembut"], "Buku teks: atom sulfur membentuk rangkai silang antara rantai polimer; rantai sukar menggelongsor dan strukturnya sukar diputuskan oleh haba.", "H"),
      Q("Mengapakah getah asli tidak sesuai untuk membuat tayar?", "Ia lembut dan tidak tahan haba, maka akan menjadi lembik apabila terkena jalan raya yang panas", ["Ia terlalu keras dan rapuh", "Ia konduktor elektrik yang baik", "Ia tidak kenyal dan telap terhadap udara"], "Buku teks: getah asli lembut dan tidak tahan haba; di Malaysia yang panas, tayar getah asli menjadi lembik dan mencair.", "M"),
      Q("Antara berikut, yang manakah ciri getah tervulkan?", "Tahan haba, penebat elektrik yang baik dan tidak telap terhadap cecair dan udara", ["Lembut dan tidak tahan haba", "Konduktor elektrik yang baik", "Mudah bertindak balas dengan asid dan alkali"], "Buku teks: getah tervulkan keras dan lebih kenyal, tahan haba, penebat elektrik yang baik, tidak telap terhadap cecair dan udara, tidak mudah teroksida dan tidak bertindak balas dengan asid dan alkali.", "M"),
      Q("Getah tervulkan sesuai digunakan untuk membuat ...", "tayar kenderaan, sarung tangan getah dan tapak kasut", ["bekas pembungkusan peralatan elektrik", "cermin pesawat", "radas kaca makmal"], "Buku teks: getah tervulkan sesuai untuk tayar kenderaan, sarung tangan getah dan tapak kasut.", "L")
    ],

